//! Encodings and placements of the proved slab routines (kernels generated by
//! `gen_routines.py`), and the driver that measures them:
//!
//!   roofline-kernels routines sizes
//!   roofline-kernels routines sweep VARIANT[,VARIANT...]
//!   roofline-kernels routines place VARIANT@POP/PUSH[,...]   (0-63, `e` end on a line, `m` split)
//!   roofline-kernels routines inline
//!
//! Every measurement is repeated in RF_ROUNDS rounds (default 3), each round running every item
//! once, so the items compared are interleaved; within a round each item runs RF_REPS times
//! (default 4) and the first is a warm-up. A cell reports the fastest repetition over all rounds,
//! and `+x` is how much slower the slowest round's best was. CPU utilization of RF_WATCH (default
//! 3,18,19) over the whole run is printed at the end, as a check that the neighbours were idle.
use crate::kernels::Kernel;
use crate::Counter;

include!(concat!(env!("OUT_DIR"), "/routines.rs"));

const CLASS: usize = 3;
const MASK: u32 = 496;
const FILL: usize = 40;
/// Placements by size, as `gen_routines.py` names them: end on a line boundary, split in half.
const END: i32 = -1;
const MID: i32 = -2;

pub struct Ctx {
    pub cycles: Counter,
    pub instrs: Counter,
    pub uops: Option<Counter>,
    pub mags: *mut u8,
    pub arena: *mut u8,
    pub arr: *mut u8,
    pub rseq: *const u32,
    pub iters: u64,
}

#[derive(Clone, Copy)]
struct Meas {
    cyc: f64,
    uops: f64,
}

extern "C" {
    static mut rk_masks: [u32; 512];
    static mut rk_masks8: [u64; 384];
    static mut rk_masks8x: [u64; 256];
    static mut rk_masks16: [u16; 512];
    static mut rk_slabs: [u8; 0];
    static mut rf_abort_count: u64;
}

impl Ctx {
    fn word(&self) -> *mut u64 {
        // SAFETY: the thread is pinned, so the CPU number read here is the one the routines read,
        // and it is below 8192 (checked), so the word lies inside `rk_slabs`.
        unsafe {
            let cpu = self.rseq.add(1).read_volatile() as usize;
            assert!(cpu < 8192, "no rseq registration");
            (&raw mut rk_slabs as *mut u8).add(cpu * 4096 + CLASS * 8) as *mut u64
        }
    }

    /// A 64-slot magazine holding `FILL` objects, loaded for the class on this CPU.
    fn prepare(&self) -> u64 {
        unsafe {
            rk_masks[CLASS] = MASK;
            rk_masks8[CLASS] = MASK as u64;
            rk_masks8x[CLASS] = MASK as u64;
            rk_masks16[CLASS] = MASK as u16;
            let m = self.mags as *mut u64;
            for i in 0..FILL {
                m.add(1 + i).write(self.arena.add(64 * i) as u64);
            }
            let top = self.mags.add(8 * (1 + FILL)) as u64;
            self.word().write(top);
            top
        }
    }

    fn measure(&self, f: Kernel, pop: *const u8, push: *const u8, ops: u64) -> Meas {
        let reps: usize = std::env::var("RF_REPS").ok().and_then(|s| s.parse().ok()).unwrap_or(4);
        let n = (self.iters / ops).max(1);
        let mut best = Meas { cyc: f64::MAX, uops: 0.0 };
        for rep in 0..reps {
            let top = self.prepare();
            let a0 = unsafe { rf_abort_count };
            self.cycles.start();
            self.instrs.start();
            if let Some(u) = &self.uops {
                u.start()
            }
            unsafe { f(n, pop as *mut u8, push as u64, self.arr, CLASS as u64) };
            let u = self.uops.as_ref().map(|u| u.stop()).unwrap_or(0);
            self.instrs.stop();
            let c = self.cycles.stop();
            let aborts = unsafe { rf_abort_count } - a0;
            // A wrong routine would leave the magazine somewhere else.
            assert_eq!(unsafe { self.word().read() }, top, "magazine not restored");
            let d = (n * ops) as f64;
            let m = Meas { cyc: c as f64 / d, uops: u as f64 / d };
            if std::env::var_os("RF_VERBOSE").is_some() {
                eprintln!("  rep {rep}: {:.3} cyc {:.2} uops {aborts} aborts", m.cyc, m.uops);
            }
            if (rep > 0 || reps == 1) && m.cyc < best.cyc && aborts * 1000 < n {
                best = m;
            }
        }
        best
    }
}

struct Routine {
    variant: &'static str,
    push: bool,
    offset: i32,
    entry: *const u8,
    bytes: usize,
    uops: u32,
}

fn table() -> Vec<Routine> {
    routines()
        .into_iter()
        .map(|(variant, push, offset, entry, end, uops)| Routine {
            variant,
            push,
            offset,
            entry,
            bytes: end as usize - entry as usize,
            uops,
        })
        .collect()
}

fn find<'a>(t: &'a [Routine], v: &str, push: bool, k: i32) -> &'a Routine {
    t.iter()
        .find(|r| r.variant == v && r.push == push && r.offset == k)
        .unwrap_or_else(|| panic!("no routine {v} {} at {k}", if push { "push" } else { "pop" }))
}

type Entry = (&'static str, Kernel, u64, &'static str, &'static str, i32, i32, &'static str);

fn kernel(name: &str) -> &'static Entry {
    KERNELS.iter().find(|k| k.0 == name).unwrap_or_else(|| panic!("no kernel {name}"))
}

/// The direct-call kernel for a variant with pop at `pk` and push at `qk` (-1: end on a line, -2: split in half).
fn call_kernel(v: &str, pk: i32, qk: i32, form: &str) -> &'static Entry {
    KERNELS
        .iter()
        .find(|k| k.4 == v && k.5 == pk && k.6 == qk && k.7 == form)
        .unwrap_or_else(|| panic!("no {form} kernel for {v} at {pk}/{qk}"))
}

/// Runs `items` in interleaved rounds; returns per item the best and the spread of round bests.
fn rounds(ctx: &Ctx, items: &[(Kernel, u64)]) -> Vec<(Meas, f64)> {
    let r: usize = std::env::var("RF_ROUNDS").ok().and_then(|s| s.parse().ok()).unwrap_or(3);
    let mut best = vec![(Meas { cyc: f64::MAX, uops: 0.0 }, 0.0f64); items.len()];
    let mut worst = vec![0.0f64; items.len()];
    for _ in 0..r {
        for (i, &(f, ops)) in items.iter().enumerate() {
            let m = ctx.measure(f, std::ptr::null(), std::ptr::null(), ops);
            if m.cyc < best[i].0.cyc {
                best[i].0 = m;
            }
            worst[i] = worst[i].max(m.cyc);
        }
    }
    for (b, w) in best.iter_mut().zip(worst) {
        b.1 = w - b.0.cyc;
    }
    best
}

fn cpu_times() -> Vec<(u64, u64)> {
    let s = std::fs::read_to_string("/proc/stat").unwrap_or_default();
    s.lines()
        .filter(|l| l.starts_with("cpu") && l.as_bytes().get(3).is_some_and(|b| b.is_ascii_digit()))
        .map(|l| {
            let v: Vec<u64> = l.split_whitespace().skip(1).filter_map(|x| x.parse().ok()).collect();
            let total: u64 = v.iter().sum();
            (total, v.get(3).copied().unwrap_or(0) + v.get(4).copied().unwrap_or(0))
        })
        .collect()
}

pub fn main(ctx: &Ctx, args: &[String]) {
    let watch: Vec<usize> = std::env::var("RF_WATCH")
        .unwrap_or_else(|_| "3,18,19".into())
        .split(',')
        .filter_map(|s| s.parse().ok())
        .collect();
    let t0 = cpu_times();
    let t = table();
    let mode = args.first().map(|s| s.as_str()).unwrap_or("sizes");
    let list: Vec<&str> = args.get(1).map(|s| s.split(',').collect()).unwrap_or_default();
    match mode {
        "sizes" => sizes(&t),
        "sweep" => {
            for v in list {
                sweep(ctx, &t, v)
            }
        }
        "place" => place(ctx, &t, &list),
        "inline" => inline(ctx, &t),
        _ => panic!("unknown mode {mode}"),
    }
    let t1 = cpu_times();
    let busy: Vec<String> = watch
        .iter()
        .filter_map(|&c| {
            let (a, b) = (t0.get(c)?, t1.get(c)?);
            let total = b.0 - a.0;
            if total == 0 {
                return Some(format!("cpu{c} n/a"));
            }
            Some(format!("cpu{c} {:.1}%", 100.0 * (1.0 - (b.1 - a.1) as f64 / total as f64)))
        })
        .collect();
    println!("busy during run: {}", busy.join(", "));
}

fn sizes(t: &[Routine]) {
    println!("{:<8} {:>6} {:>9} {:>7} {:>9}", "variant", "pop B", "pop uops", "push B", "push uops");
    let mut seen = Vec::new();
    for r in t.iter().filter(|r| r.offset == 0 && !r.push) {
        if seen.contains(&r.variant) {
            continue;
        }
        seen.push(r.variant);
        let q = find(t, r.variant, true, 0);
        println!("{:<8} {:>6} {:>9} {:>7} {:>9}", r.variant, r.bytes, r.uops, q.bytes, q.uops);
    }
}

/// Each routine at every offset, the other split in half by a line boundary (`m`): the swept
/// routine is the only change.
fn sweep(ctx: &Ctx, t: &[Routine], v: &str) {
    let (p0, q0) = (find(t, v, false, 0), find(t, v, true, 0));
    let mut items = Vec::new();
    for k in 0..64 {
        for (pk, qk) in [(k, MID), (MID, k)] {
            for form in ["pair", "batch"] {
                let e = call_kernel(v, pk, qk, form);
                items.push((e.1, e.2));
            }
        }
    }
    let res = rounds(ctx, &items);
    let (pm, qm) = (find(t, v, false, MID), find(t, v, true, MID));
    println!(
        "sweep {v}: pop {} B {} uops, push {} B {} uops; the other at {}/{}; cycles per alloc+free, the slowest round's best after +",
        p0.bytes,
        p0.uops,
        q0.bytes,
        q0.uops,
        pm.entry as usize % 64,
        qm.entry as usize % 64
    );
    println!("{:>3}  {:>13} {:>13}  {:>13} {:>13}", "k", "pop@k pair", "pop@k batch", "push@k pair", "push@k batch");
    for k in 0..64 {
        let c = |i: usize| format!("{:.2} +{:.2}", res[4 * k + i].0.cyc, res[4 * k + i].1);
        println!("{k:>3}  {:>13} {:>13}  {:>13} {:>13}", c(0), c(1), c(2), c(3));
    }
}

/// Placements VARIANT@POP/PUSH, each 0 to 63, `e` (end on a line boundary) or `m` (split in
/// half by one); a direct-call kernel exists when either is `m`, or for 0/0 and e/e.
fn place(ctx: &Ctx, t: &[Routine], list: &[&str]) {
    let mut items = Vec::new();
    let mut rows = Vec::new();
    for spec in list {
        let (v, offs) = spec.split_once('@').unwrap_or((spec, "0/0"));
        let (a, b) = offs.split_once('/').expect("VARIANT@POP/PUSH");
        let k = |s: &str| match s {
            "e" => END,
            "m" => MID,
            _ => s.parse::<i32>().expect("offset"),
        };
        let (pk, qk) = (k(a), k(b));
        let (p, q) = (find(t, v, false, pk), find(t, v, true, qk));
        for form in ["pair", "batch"] {
            let e = call_kernel(v, pk, qk, form);
            items.push((e.1, e.2));
        }
        rows.push((v, p, q));
    }
    let res = rounds(ctx, &items);
    println!(
        "{:<8} {:>7} {:>7} {:>7} {:>14} {:>8} {:>14} {:>8}",
        "variant", "offsets", "pop B/u", "push B/u", "call pair cyc", "uops/op", "call batch cyc", "uops/op"
    );
    for (i, (v, p, q)) in rows.iter().enumerate() {
        let (a, b) = (res[2 * i], res[2 * i + 1]);
        let off = |r: &Routine| r.entry as usize % 64;
        println!(
            "{:<8} {:>7} {:>7} {:>7} {:>8.2} +{:<4.2} {:>8.2} {:>8.2} +{:<4.2} {:>8.2}",
            v,
            format!("{}/{}", off(p), off(q)),
            format!("{}/{}", p.bytes, p.uops),
            format!("{}/{}", q.bytes, q.uops),
            a.0.cyc,
            a.1,
            a.0.uops,
            b.0.cyc,
            b.1,
            b.0.uops
        );
    }
}

/// The inline variants in pair and batch loops, and the generated routines called directly and
/// through registers at offset 0.
fn inline(ctx: &Ctx, t: &[Routine]) {
    let mut rows: Vec<(String, String, Kernel, u64, Kernel, u64, *const u8, *const u8)> = Vec::new();
    for (name, pu, qu) in INLINE_UOPS {
        let (a, b) = (kernel(&format!("gp_{name}")), kernel(&format!("gb_{name}")));
        rows.push((name.to_string(), format!("{pu}/{qu}"), a.1, a.2, b.1, b.2, std::ptr::null(), std::ptr::null()));
    }
    let (p, q) = (find(t, "gen", false, 0), find(t, "gen", true, 0));
    let (a, b) = (call_kernel("gen", 0, 0, "pair"), call_kernel("gen", 0, 0, "batch"));
    rows.push(("gen, direct calls".into(), "16/16".into(), a.1, a.2, b.1, b.2, std::ptr::null(), std::ptr::null()));
    let (a, b) = (kernel("gx_cpair"), kernel("gx_cbatch"));
    rows.push(("gen, calls via reg".into(), "16/16".into(), a.1, a.2, b.1, b.2, p.entry, q.entry));
    let r: usize = std::env::var("RF_ROUNDS").ok().and_then(|s| s.parse().ok()).unwrap_or(3);
    let mut best = vec![[(f64::MAX, 0.0, 0.0f64); 2]; rows.len()];
    for _ in 0..r {
        for (i, row) in rows.iter().enumerate() {
            for (j, (f, ops)) in [(row.2, row.3), (row.4, row.5)].into_iter().enumerate() {
                let m = ctx.measure(f, row.6, row.7, ops);
                let c = &mut best[i][j];
                if m.cyc < c.0 {
                    c.0 = m.cyc;
                    c.1 = m.uops;
                }
                c.2 = c.2.max(m.cyc);
            }
        }
    }
    println!("{:<20} {:>9} {:>14} {:>8} {:>14} {:>8}", "inline variant", "uops p/p", "pair cyc", "uops/op", "batch cyc", "uops/op");
    for (row, b) in rows.iter().zip(best) {
        println!(
            "{:<20} {:>9} {:>8.2} +{:<4.2} {:>8.2} {:>8.2} +{:<4.2} {:>8.2}",
            row.0,
            row.1,
            b[0].0,
            b[0].2 - b[0].0,
            b[0].1,
            b[1].0,
            b[1].2 - b[1].0,
            b[1].1
        );
    }
}
